<?php
declare(strict_types=1);
require_once dirname(__DIR__, 2) . '/core/Authorization.php';
require_once __DIR__ . '/ProprietaireController.php';
$user = Authorization::requireRole('Administrateur plateforme', 'Administrateur agence', 'Gestionnaire immobilier');
$agencyId = (int) ($user['id_agence'] ?? 0); $ownerId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
if ($agencyId < 1 || !$ownerId) { http_response_code(400); exit('Parametres invalides.'); }
$owner = ProprietaireModel::find($agencyId, $ownerId); if (!$owner) { http_response_code(404); exit('Proprietaire introuvable.'); }
$errors = []; $success = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
	if (!Auth::verifyCsrf($_POST['csrf_token'] ?? null)) { $errors['general'] = 'Votre session a expire. Rechargez la page.'; }
	elseif (($_POST['action'] ?? '') === 'attach') { try { [$errors] = ProprietaireController::attach($agencyId, $ownerId, $_POST); if ($errors === []) { $success = 'Le bien a ete associe.'; } } catch (Throwable $exception) { error_log($exception->getMessage()); $errors['general'] = 'Impossible d’associer ce bien.'; } }
	elseif (($_POST['action'] ?? '') === 'detach') { try { ProprietaireModel::detachProperty($agencyId, $ownerId, (int) $_POST['id_bien']); $success = 'L’association a ete retiree.'; } catch (Throwable $exception) { error_log($exception->getMessage()); $errors['general'] = 'Impossible de retirer cette association.'; } }
}
$properties = ProprietaireModel::properties($agencyId, $ownerId); $available = ProprietaireModel::availableProperties($agencyId, $ownerId); $csrfToken = Auth::csrfToken();
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Proprietaire | LOKA</title><link rel="stylesheet" href="../biens/bien.css"></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand__mark">L</span><span>LOKA</span></a><nav class="nav"><div class="nav__label">Gestion</div><a href="../biens/index.php"><span class="nav__icon">⌂</span><span>Biens</span></a><a class="is-active" href="index.php"><span class="nav__icon">♙</span><span>Proprietaires</span></a><a href="#"><span class="nav__icon">▣</span><span>Contrats</span></a></nav></aside><div class="content"><header class="topbar"><div><div class="topbar__eyebrow">Proprietaires</div><div class="topbar__title">Fiche detaillee</div></div><a class="button button--ghost" href="index.php">Retour</a></header><main class="page"><div class="page__header"><div><h1 class="page__title"><?= htmlspecialchars($owner['prenom'] . ' ' . $owner['nom'], ENT_QUOTES, 'UTF-8') ?></h1><p class="page__subtitle"><?= htmlspecialchars((string) ($owner['email'] ?? 'Aucun e-mail'), ENT_QUOTES, 'UTF-8') ?></p></div><div class="actions"><a class="button button--secondary" href="modifier.php?id=<?= $ownerId ?>">Modifier</a><form method="post" action="supprimer.php"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= $ownerId ?>"><button class="button--danger" type="submit">Archiver</button></form></div></div><?php if ($success): ?><div class="alert alert--success"><?= htmlspecialchars($success, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><?php if (isset($errors['general'])): ?><div class="alert alert--error"><?= htmlspecialchars($errors['general'], ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><div class="detail-grid"><section class="card"><div class="card__header"><h2 class="card__title">Informations du proprietaire</h2></div><div class="card__body"><dl class="detail-list"><?php foreach (['email','telephone','adresse','code_postal','ville','pays','date_naissance','projet'] as $field): ?><div><dt><?= htmlspecialchars(str_replace('_', ' ', $field), ENT_QUOTES, 'UTF-8') ?></dt><dd><?= htmlspecialchars((string) ($owner[$field] ?? '—'), ENT_QUOTES, 'UTF-8') ?></dd></div><?php endforeach; ?></dl></div></section><section class="card"><div class="card__header"><h2 class="card__title">Associer un bien</h2></div><div class="card__body"><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="attach"><label>Bien<select name="id_bien" required><option value="">Selectionner un bien</option><?php foreach ($available as $property): ?><option value="<?= (int) $property['id_bien'] ?>"><?= htmlspecialchars($property['reference'] . ' — ' . $property['titre'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><label>Quote-part (%)<input type="number" name="quote_part" min="0.01" max="100" step="0.01" value="100"></label><label>Date de debut<input type="date" name="date_debut" required value="<?= date('Y-m-d') ?>"></label><button type="submit">Associer le bien</button></form></div></section></div><section class="card" style="margin-top:20px"><div class="card__header"><h2 class="card__title">Biens associes</h2><span class="cell-muted"><?= count($properties) ?> bien(s)</span></div><div class="table-wrap"><table><thead><tr><th>Bien</th><th>Quote-part</th><th>Date de debut</th><th></th></tr></thead><tbody><?php foreach ($properties as $property): ?><tr><td><div class="cell-title"><?= htmlspecialchars($property['titre'], ENT_QUOTES, 'UTF-8') ?></div><div class="cell-muted"><?= htmlspecialchars($property['reference'], ENT_QUOTES, 'UTF-8') ?></div></td><td><?= htmlspecialchars((string) $property['quote_part'], ENT_QUOTES, 'UTF-8') ?> %</td><td><?= htmlspecialchars($property['date_debut'], ENT_QUOTES, 'UTF-8') ?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="detach"><input type="hidden" name="id_bien" value="<?= (int) $property['id_bien'] ?>"><button class="button--danger" type="submit">Retirer</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php if ($properties === []): ?><div class="empty">Aucun bien associe.</div><?php endif; ?></section></main></div></div></body></html>